// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint128).max);

        // fund the contract through its payable fallback
        address funder = address(0xABCD);
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assert(address(c).balance == amount);

        // owner calls withdraw with fuzzed amount
        address owner = c.owner();
        vm.deal(owner, 1 wei);
        vm.prank(owner);
        bool ok; try c.withdraw(amount) { ok = true; } catch { ok = false; }

        // general rule: a successful withdraw(v) (v <= balance) must move exactly v wei out
        assertTrue(!ok || address(c).balance == amount - amount);
    }
}
